// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IUniV3Pool {
    function observe(uint32[] calldata secondsAgos)
        external
        view
        returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s);

    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function liquidity() external view returns (uint128);
    function increaseObservationCardinalityNext(uint16 observationCardinalityNext) external;
}

interface IStateView {
    function getSlot0(bytes32 poolId)
        external
        view
        returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee);

    function getLiquidity(bytes32 poolId) external view returns (uint128 liquidity);
}

interface IPosm {
    function poolKeys(bytes25 poolId)
        external
        view
        returns (address currency0, address currency1, uint24 fee, int24 tickSpacing, address hooks);
}

struct PoolKey {
    address currency0;
    address currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

/// @title UniTwap — Uniswap V3 TWAP → WETH per 1e18 token
/// @notice Tick-to-sqrtPrice uses the published 1.0001^(2^n) bit table
///         (Uniswap v3 whitepaper §6.2). No owner price feed.
library UniTwap {
    int24 internal constant MIN_TICK = -887272;
    int24 internal constant MAX_TICK = 887272;

    error BadPool();
    error Unpriced();

    function consult(address pool, uint32 secondsAgo) internal view returns (int24 meanTick) {
        if (secondsAgo == 0) revert Unpriced();
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = secondsAgo;
        secondsAgos[1] = 0;
        (int56[] memory ticks, ) = IUniV3Pool(pool).observe(secondsAgos);
        int56 delta = ticks[1] - ticks[0];
        int56 span = int56(uint56(secondsAgo));
        meanTick = int24(delta / span);
        if (delta < 0 && (delta % span != 0)) meanTick--;
    }

    /// @dev WETH wei for one full `token` (pass `10 ** decimals(token)`).
    function priceWethWad(address pool, address token, address weth, uint256 tokenUnit, uint32 secondsAgo)
        internal
        view
        returns (uint256)
    {
        address t0 = IUniV3Pool(pool).token0();
        address t1 = IUniV3Pool(pool).token1();
        if (!((token == t0 && weth == t1) || (token == t1 && weth == t0))) revert BadPool();
        int24 tick = consult(pool, secondsAgo);
        uint256 px = quoteAtTick(tick, tokenUnit, token == t0);
        if (px == 0) revert Unpriced();
        return px;
    }

    /// @dev Quote-token amount for one full `base` through a V3 TWAP. Pool must be base/quote.
    function quotePerBase(address pool, address base, address quote, uint256 baseUnit, uint32 secondsAgo)
        internal
        view
        returns (uint256)
    {
        address t0 = IUniV3Pool(pool).token0();
        address t1 = IUniV3Pool(pool).token1();
        if (!((base == t0 && quote == t1) || (base == t1 && quote == t0))) revert BadPool();
        int24 tick = consult(pool, secondsAgo);
        uint256 out = quoteAtTick(tick, baseUnit, base == t0);
        if (out == 0) revert Unpriced();
        return out;
    }

    /// @dev V4 has no observe(). Spot tick from StateView. Native ETH counts as WETH.
    function priceWethWadV4(
        address stateView,
        bytes32 poolId,
        address token,
        address c0,
        address c1,
        address weth,
        uint256 tokenUnit
    ) internal view returns (uint256) {
        address other = token == c0 ? c1 : (token == c1 ? c0 : address(0));
        if (other != weth && other != address(0)) revert BadPool();
        if (token != c0 && token != c1) revert BadPool();
        (, int24 tick, , ) = IStateView(stateView).getSlot0(poolId);
        uint256 px = quoteAtTick(tick, tokenUnit, token == c0);
        if (px == 0) revert Unpriced();
        return px;
    }

    function quoteAtTick(int24 tick, uint256 baseAmount, bool token0In) internal pure returns (uint256) {
        uint256 sqrtP = uint256(getSqrtRatioAtTick(tick));
        if (token0In) {
            return mulDiv(mulDiv(baseAmount, sqrtP, 1 << 96), sqrtP, 1 << 96);
        }
        return mulDiv(mulDiv(baseAmount, 1 << 96, sqrtP), 1 << 96, sqrtP);
    }

    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        unchecked {
            uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
            if (absTick > uint256(uint24(MAX_TICK))) revert Unpriced();

            uint256 ratio = absTick & 0x1 != 0
                ? 0xfffcb933bd6fad37aa2d162d1a594001
                : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

            if (tick > 0) ratio = type(uint256).max / ratio;
            sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }

    /// @dev 512-bit mulDiv (solmate-style).
    function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 z) {
        unchecked {
            if (denominator == 0) revert Unpriced();
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(x, y, not(0))
                prod0 := mul(x, y)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) {
                return prod0 / denominator;
            }
            if (prod1 >= denominator) revert Unpriced();

            uint256 remainder;
            assembly {
                remainder := mulmod(x, y, denominator)
            }
            assembly {
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = denominator & (0 - denominator);
            assembly {
                denominator := div(denominator, twos)
            }
            assembly {
                prod0 := div(prod0, twos)
            }
            assembly {
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;

            uint256 inv = (3 * denominator) ^ 2;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            z = prod0 * inv;
        }
    }
}

interface IUniTwapOracle {
    function priceWethWad(address pool, address token, address weth, uint256 tokenUnit, uint32 secondsAgo)
        external
        view
        returns (uint256);

    function quotePerBase(address pool, address base, address quote, uint256 baseUnit, uint32 secondsAgo)
        external
        view
        returns (uint256);

    function priceWethWadV4(
        address stateView,
        bytes32 poolId,
        address token,
        address c0,
        address c1,
        address weth,
        uint256 tokenUnit
    ) external view returns (uint256);

    function quoteAtTick(int24 tick, uint256 baseAmount, bool token0In) external pure returns (uint256);
}

/// @dev Deployed helper so HoodxIndex stays under the 24kb clone limit.
contract UniTwapOracle {
    function priceWethWad(address pool, address token, address weth, uint256 tokenUnit, uint32 secondsAgo)
        external
        view
        returns (uint256)
    {
        return UniTwap.priceWethWad(pool, token, weth, tokenUnit, secondsAgo);
    }

    function quotePerBase(address pool, address base, address quote, uint256 baseUnit, uint32 secondsAgo)
        external
        view
        returns (uint256)
    {
        return UniTwap.quotePerBase(pool, base, quote, baseUnit, secondsAgo);
    }

    function priceWethWadV4(
        address stateView,
        bytes32 poolId,
        address token,
        address c0,
        address c1,
        address weth,
        uint256 tokenUnit
    ) external view returns (uint256) {
        return UniTwap.priceWethWadV4(stateView, poolId, token, c0, c1, weth, tokenUnit);
    }

    function quoteAtTick(int24 tick, uint256 baseAmount, bool token0In) external pure returns (uint256) {
        return UniTwap.quoteAtTick(tick, baseAmount, token0In);
    }
}

contracts/HoodxStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IUniV3Pool, IStateView, IPosm, PoolKey} from "./UniTwap.sol";

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function decimals() external view returns (uint8);
}

interface IWETH is IERC20 {
    function deposit() external payable;
    function withdraw(uint256) external;
}

interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256);
}

interface IPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    function unlock(bytes calldata data) external returns (bytes memory);
    function swap(PoolKey memory key, SwapParams memory params, bytes calldata hookData) external returns (int256);
    function sync(address currency) external;
    function settle() external payable returns (uint256);
    function take(address currency, address to, uint256 amount) external;
}

/// @dev Shared clone storage. HoodxIndex and HoodxSwap must keep this layout identical.
contract HoodxStorage {
    uint256 public constant BPS_DENOM = 10_000;
    uint256 public constant MAX_FEE_BPS = 100;
    uint32 public constant TWAP_SECS = 60;
    uint16 public constant MAX_SLIP_BPS = 300;
    uint16 public constant MIN_CASH_BPS = 2000;
    uint16 public constant MAX_POOL_TAKE_BPS = 2000;
    uint16 public constant MAX_NEW_BUY_BPS = 500;
    uint64 public constant BUY_UNLOCK_DELAY = 1 hours;
    uint64 public constant NEW_NAME_GUARD = 1 days;
    uint256 public constant MIN_POOL_WETH = 0.02 ether;
    uint256 public constant MIN_POOL_USDG = 50 * 1e6;
    uint16 public constant ORACLE_CARDINALITY = 16;
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;
    uint8 public constant decimals = 18;
    address internal constant USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168;
    address internal constant WETH_USDG_V3 = 0x52e65B17fB6E5BA00Ed806f37Afcd2DaA50271Ca;
    uint256 public constant VIRTUAL_ASSETS = 1e12;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    string public name;
    string public symbol;
    address public factory;
    address public owner;
    address public pendingOwner;
    address public creator;
    address public creatorRecipient;
    address public protocol;
    address public weth;
    address public swapRouter;
    address public v4Manager;
    address public v4StateView;
    address public v4Posm;
    address[] public tokens;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint16) public targetBps;
    mapping(address => uint256) public costBasis;
    mapping(address => bool) public listed;
    mapping(address => address) public poolOf;
    mapping(address => bytes32) public poolIdOf;
    mapping(address => bool) public isV4;
    mapping(address => PoolKey) public v4Key;
    mapping(address => uint256) public lastPxWad;
    mapping(address => address) public quoteOf;
    mapping(address => bool) public allowedQuote;
    mapping(address => address) public quoteBridgeV3;

    uint256 public totalSupply;
    uint16 public protocolFeeBps;
    uint16 public creatorFeeBps;
    uint16 public redeemFeeBps;
    uint16 public cashTargetBps;
    uint256 public minDeposit;
    uint256 public minFirstDeposit;
    uint256 public minSleeveWeth;
    uint256 public genesisEthPerShare;
    bool public paused;
    string public imageURI;
    uint256 internal locked;
    bool internal implLock;
    mapping(address => uint64) public listedAt;
    mapping(address => uint256) public strandedBag;
    mapping(address => uint256) public strandedSupply;
    mapping(address => mapping(address => bool)) public strandedClaimed;

    error NotOwner();
    error NotCreator();
    error BadOwner();
    error Zero();
    error BadLen();
    error TooSmall();
    error DustSleeve();
    error NeedBuffer();
    error Paused();
    error TransferFailed();
    error Listed();
    error CashFloor();
    error MaxFee();
    error SwapFailed();
    error Unpriced();
    error AlreadyInit();
    error BadPair();
    error Slippage();
    error BadPool();
    error HookedPool();
    error ThinPool();
    error TooSoon();
    error AlreadyClaimed();
    error NotManager();
    error OnlySelf();
    error Started();

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Deposit(address indexed user, uint256 ethIn, uint256 shares, uint256 protocolFee, uint256 creatorFee, uint256 sharePrice);
    event Withdraw(address indexed user, uint256 shares, uint256 ethOut, uint256 fee, uint256 sharePrice);
    event Deployed(uint256 wethSpent, uint256 names);
    event Liquidated(uint256 shares, uint256 names);
    event Targets(address[] tokens, uint16[] bps);
    event Rebalanced(address indexed tokenIn, address indexed tokenOut, uint256 amountIn, uint256 minOut);
    event Restored(address indexed token, uint256 amountIn, uint256 minOut);
    event CreatorFee(uint16 bps);
    event CreatorRecipient(address indexed who);
    event TokenAdded(address indexed token, bytes32 poolRef, bool v4);
    event TokenRebound(address indexed token, bytes32 poolRef, bool v4);
    event TokenRemoved(address indexed token);
    event TokenStranded(address indexed token, uint256 balance);
    event DustClaimed(address indexed user, address indexed token, uint256 amount);
    event Floors(uint256 minDeposit, uint256 minFirst, uint256 minSleeve, uint16 cashBps);
    event Genesis(uint256 ethPerShare);
    event PausedSet(bool paused);
    event OwnerSet(address indexed owner);
    event OwnershipTransferStarted(address indexed from, address indexed to);
    event OwnershipTransferCanceled(address indexed owner, address indexed pending);
    event QuoteBridgeSet(address indexed quote, address indexed v3Bridge);
    event ImageURISet(string uri);

    struct InitParams {
        address creator;
        address protocol;
        address weth;
        address router;
        address v4Manager;
        address v4StateView;
        address v4Posm;
        string name;
        string symbol;
        uint16 protocolFeeBps;
        uint16 creatorFeeBps;
        uint256 minFirstDeposit;
        address recipient;
        string imageURI;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier nonReentrant() {
        if (locked != 0) revert SwapFailed();
        locked = 1;
        _;
        locked = 0;
    }
}

contracts/HoodxSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IUniTwapOracle, IUniV3Pool, IStateView, IPosm, PoolKey} from "./UniTwap.sol";
import {HoodxStorage, IERC20, IWETH, ISwapRouter02, IPoolManager} from "./HoodxStorage.sol";

interface IHoodxView {
    function priceWethWad(address token) external view returns (uint256);
    function minOutFloor(uint256 twapOut) external pure returns (uint256);
}

/// @dev Swap / bind / quote-seed logic. HoodxIndex delegatecalls this so the clone stays under 24kb.
contract HoodxSwap is HoodxStorage {
    address public immutable twapOracle;

    constructor(address twapOracle_) {
        if (twapOracle_ == address(0)) revert Zero();
        twapOracle = twapOracle_;
        implLock = true;
    }

    function swap(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin) external payable {
        address listedTok = tokenIn == weth ? tokenOut : tokenIn;
        if (tokenOut == weth && listed[listedTok]) {
            if (isV4[listedTok]) {
                if (v4Key[listedTok].hooks != address(0)) return;
                if (IStateView(v4StateView).getLiquidity(poolIdOf[listedTok]) == 0) return;
            } else {
                address sellPool = poolOf[listedTok];
                if (sellPool == address(0) || IUniV3Pool(sellPool).liquidity() == 0) return;
            }
        }
        if (tokenIn == weth && listed[tokenOut]) {
            _guardBuy(tokenOut, amountIn);
        }
        address quote = quoteOf[listedTok];
        if (quote != address(0) && quote != weth) {
            if (tokenIn == weth && tokenOut == listedTok) {
                _swapQuotedBuy(listedTok, quote, amountIn, amountOutMin);
                return;
            }
            if (tokenOut == weth && tokenIn == listedTok) {
                _swapQuotedSell(listedTok, quote, amountIn, amountOutMin);
                return;
            }
            revert BadPair();
        }
        if (isV4[listedTok]) {
            if (amountIn > uint256(uint128(type(int128).max))) revert Zero();
            IPoolManager(v4Manager).unlock(abi.encode(tokenIn, tokenOut, amountIn, amountOutMin));
            return;
        }
        address pool = poolOf[listedTok];
        if (pool == address(0)) revert BadPair();
        _swapV3Exact(tokenIn, tokenOut, pool, amountIn, amountOutMin);
    }

    function unlockCallback(bytes calldata data) external payable returns (bytes memory) {
        if (msg.sender != v4Manager) revert NotManager();
        (address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin) =
            abi.decode(data, (address, address, uint256, uint256));
        address listedTok;
        if (tokenIn == weth) listedTok = tokenOut;
        else if (tokenOut == weth) listedTok = tokenIn;
        else if (listed[tokenOut]) listedTok = tokenOut;
        else listedTok = tokenIn;
        if (!isV4[listedTok]) revert BadPair();
        PoolKey memory key = v4Key[listedTok];
        bool native = key.currency0 == address(0) || key.currency1 == address(0);
        address currencyIn = tokenIn == weth && native ? address(0) : tokenIn;
        address currencyOut = tokenOut == weth && native ? address(0) : tokenOut;
        bool zeroForOne = currencyIn == key.currency0;
        if ((zeroForOne && currencyOut != key.currency1) || (!zeroForOne && currencyIn != key.currency1)) {
            revert BadPool();
        }
        IPoolManager pm = IPoolManager(v4Manager);
        int256 raw = pm.swap(
            key,
            IPoolManager.SwapParams({
                zeroForOne: zeroForOne,
                amountSpecified: -int256(amountIn),
                sqrtPriceLimitX96: zeroForOne ? MIN_SQRT_RATIO + 1 : MAX_SQRT_RATIO - 1
            }),
            ""
        );
        int128 d0;
        int128 d1;
        assembly {
            d0 := sar(128, raw)
            d1 := signextend(15, raw)
        }
        int128 dIn = zeroForOne ? d0 : d1;
        int128 dOut = zeroForOne ? d1 : d0;
        if (dIn >= 0 || dOut <= 0) revert SwapFailed();
        uint256 paid = uint256(uint128(-dIn));
        uint256 got = uint256(uint128(dOut));
        if (got < amountOutMin) revert Slippage();
        if (currencyIn == address(0)) {
            IWETH(weth).withdraw(paid);
            pm.settle{value: paid}();
        } else {
            pm.sync(currencyIn);
            if (!IERC20(currencyIn).transfer(address(pm), paid)) revert TransferFailed();
            pm.settle();
        }
        pm.take(currencyOut, address(this), got);
        if (currencyOut == address(0)) {
            IWETH(weth).deposit{value: got}();
        }
        return abi.encode(got);
    }

    function addTokenRaw(address token, bytes32 poolRef) external payable {
        _addToken(token, poolRef);
    }

    function removeTokenRaw(address token) external payable {
        _removeToken(token);
    }

    function clearBindRaw(address token) external payable {
        if (!listed[token]) revert Listed();
        _clearBind(token);
    }

    /// @dev Drop a name from the index but leave its bag in the vault (unredeemable dust).
    function strandTokenRaw(address token) external payable {
        _strandToken(token);
    }

    function claimDustRaw(address token) external payable {
        if (listed[token]) revert Listed();
        uint256 supply = strandedSupply[token];
        uint256 bag = strandedBag[token];
        if (supply == 0 || bag == 0) revert Zero();
        if (strandedClaimed[token][msg.sender]) revert AlreadyClaimed();
        uint256 shares = balanceOf[msg.sender];
        if (shares == 0) revert Zero();
        strandedClaimed[token][msg.sender] = true;
        uint256 amt = (bag * shares) / supply;
        uint256 have = IERC20(token).balanceOf(address(this));
        if (amt > have) amt = have;
        if (amt == 0) revert Zero();
        if (!IERC20(token).transfer(msg.sender, amt)) revert TransferFailed();
        emit DustClaimed(msg.sender, token, amt);
    }

    function rebindTokenRaw(address token, bytes32 poolRef) external payable {
        if (!listed[token]) revert Listed();
        if (IERC20(token).balanceOf(address(this)) != 0) revert NeedBuffer();
        _clearBind(token);
        if (uint256(poolRef) >> 160 == 0) {
            address pool = address(uint160(uint256(poolRef)));
            _bindPool(token, pool);
            poolOf[token] = pool;
            emit TokenRebound(token, poolRef, false);
        } else {
            _bindV4(token, poolRef);
            emit TokenRebound(token, poolRef, true);
        }
    }

    function initQuotes() external payable {
        _initRhQuotes();
    }

    function setQuoteBridgeRaw(address quote, address v3Bridge) external payable {
        if (quote == address(0) || v3Bridge == address(0) || quote == weth) revert Zero();
        uint8 dec = IERC20(quote).decimals();
        if (quote == USDG) {
            if (dec != 6) revert BadPool();
        } else if (dec != 18) {
            revert BadPool();
        }
        address t0 = IUniV3Pool(v3Bridge).token0();
        address t1 = IUniV3Pool(v3Bridge).token1();
        if (!((quote == t0 && weth == t1) || (quote == t1 && weth == t0))) revert BadPool();
        IUniV3Pool(v3Bridge).fee();
        allowedQuote[quote] = true;
        quoteBridgeV3[quote] = v3Bridge;
        emit QuoteBridgeSet(quote, v3Bridge);
    }

    function setImageURIRaw(string calldata uri) external payable {
        _setImageURI(uri);
    }

    /// @dev Payable: Index deposit is payable and delegatecall preserves msg.value.
    function warmOracleRaw(address token) external payable {
        if (isV4[token]) return;
        address pool = poolOf[token];
        if (pool == address(0)) revert Listed();
        IUniV3Pool(pool).increaseObservationCardinalityNext(ORACLE_CARDINALITY);
    }

    function _addToken(address token, bytes32 poolRef) internal {
        if (token == address(0) || token == weth || listed[token]) revert Listed();
        if (tokens.length >= 24) revert BadLen();
        if (uint256(poolRef) >> 160 == 0) {
            address pool = address(uint160(uint256(poolRef)));
            _bindPool(token, pool);
            poolOf[token] = pool;
            emit TokenAdded(token, poolRef, false);
        } else {
            _bindV4(token, poolRef);
            emit TokenAdded(token, poolRef, true);
        }
        listed[token] = true;
        tokens.push(token);
        uint256 live = totalSupply > balanceOf[DEAD] ? totalSupply - balanceOf[DEAD] : 0;
        listedAt[token] = live == 0 ? uint64(1) : uint64(block.timestamp);
    }

    function _bindPool(address token, address pool) internal {
        if (pool == address(0) || pool.code.length == 0) revert BadPool();
        address t0 = IUniV3Pool(pool).token0();
        address t1 = IUniV3Pool(pool).token1();
        if ((token == t0 && weth == t1) || (token == t1 && weth == t0)) {
            quoteOf[token] = weth;
        } else if ((token == t0 && USDG == t1) || (token == t1 && USDG == t0)) {
            if (!allowedQuote[USDG] || quoteBridgeV3[USDG] == address(0)) revert BadPool();
            quoteOf[token] = USDG;
        } else revert BadPool();
        if (IERC20(token).decimals() != 18) revert BadPool();
        IUniV3Pool(pool).fee();
        _assertV3Depth(pool, quoteOf[token]);
    }

    function _assertV3Depth(address pool, address quote) internal view {
        if (IUniV3Pool(pool).liquidity() == 0) revert ThinPool();
        if (quote == weth) {
            if (IERC20(weth).balanceOf(pool) < MIN_POOL_WETH) revert ThinPool();
        } else if (quote == USDG) {
            if (IERC20(USDG).balanceOf(pool) < MIN_POOL_USDG) revert ThinPool();
        }
    }

    function _guardBuy(address token, uint256 amountIn) internal view {
        uint64 added = listedAt[token];
        if (added > 1 && block.timestamp < uint256(added) + BUY_UNLOCK_DELAY) revert TooSoon();
        uint256 assets = IERC20(weth).balanceOf(address(this)) + address(this).balance;
        uint256 cap = (assets * uint256(MAX_POOL_TAKE_BPS)) / BPS_DENOM;
        if (!isV4[token]) {
            address pool = poolOf[token];
            if (pool != address(0)) {
                if (IUniV3Pool(pool).liquidity() == 0) revert ThinPool();
                uint256 poolCap = (IERC20(weth).balanceOf(pool) * uint256(MAX_POOL_TAKE_BPS)) / BPS_DENOM;
                if (poolCap < cap) cap = poolCap;
            }
        } else if (IStateView(v4StateView).getLiquidity(poolIdOf[token]) == 0) {
            revert ThinPool();
        }
        if (added > 1 && block.timestamp < uint256(added) + NEW_NAME_GUARD) {
            uint256 fresh = (assets * uint256(MAX_NEW_BUY_BPS)) / BPS_DENOM;
            if (fresh < cap) cap = fresh;
        }
        if (cap == 0 || amountIn > cap) revert ThinPool();
    }

    function _bindV4(address token, bytes32 poolId) internal {
        (address c0, address c1, uint24 fee, int24 spacing, address hooks) = IPosm(v4Posm).poolKeys(bytes25(poolId));
        if (c1 == address(0)) revert BadPool();
        if (hooks != address(0)) revert HookedPool();
        PoolKey memory key = PoolKey({
            currency0: c0,
            currency1: c1,
            fee: fee,
            tickSpacing: spacing,
            hooks: hooks
        });
        bytes32 hashed;
        assembly {
            hashed := keccak256(key, 0xa0)
        }
        if (hashed != poolId) revert BadPool();
        if (token != c0 && token != c1) revert BadPool();
        address other = token == c0 ? c1 : c0;
        if (other == weth || other == address(0)) {
            quoteOf[token] = weth;
        } else if (other == USDG || (allowedQuote[other] && quoteBridgeV3[other] != address(0))) {
            quoteOf[token] = other;
        } else revert BadPool();
        if (IERC20(token).decimals() != 18) revert BadPool();
        (uint160 sqrtP, , , ) = IStateView(v4StateView).getSlot0(poolId);
        if (sqrtP == 0) revert BadPool();
        if (IStateView(v4StateView).getLiquidity(poolId) == 0) revert ThinPool();
        isV4[token] = true;
        poolIdOf[token] = poolId;
        v4Key[token] = key;
    }

    function _removeToken(address token) internal {
        if (!listed[token]) revert Listed();
        if (IERC20(token).balanceOf(address(this)) != 0) revert NeedBuffer();
        _dropToken(token);
        emit TokenRemoved(token);
    }

    function _strandToken(address token) internal {
        if (!listed[token]) revert Listed();
        // Liquid names must be sold. Stranding is only for hooked V4 bags that cannot exit.
        if (!isV4[token] || v4Key[token].hooks == address(0)) revert BadPool();
        uint256 bag = IERC20(token).balanceOf(address(this));
        uint256 live = totalSupply > balanceOf[DEAD] ? totalSupply - balanceOf[DEAD] : 0;
        if (bag > 0 && live > 0) {
            strandedBag[token] = bag;
            strandedSupply[token] = live;
        }
        _dropToken(token);
        emit TokenStranded(token, bag);
    }

    function _dropToken(address token) internal {
        uint256 n = tokens.length;
        if (n <= 2) revert BadLen();
        listed[token] = false;
        targetBps[token] = 0;
        delete listedAt[token];
        _clearBind(token);
        for (uint256 i; i < n; i++) {
            if (tokens[i] == token) {
                tokens[i] = tokens[n - 1];
                tokens.pop();
                break;
            }
        }
    }

    function _clearBind(address token) internal {
        delete poolOf[token];
        delete poolIdOf[token];
        delete isV4[token];
        delete v4Key[token];
        delete quoteOf[token];
        delete lastPxWad[token];
    }

    function _seedQuoteBridge(address quote, address bridge) internal {
        allowedQuote[quote] = true;
        quoteBridgeV3[quote] = bridge;
    }

    function _initRhQuotes() internal {
        _seedQuoteBridge(USDG, WETH_USDG_V3);
        _seedQuoteBridge(0x117cc2133c37B721F49dE2A7a74833232B3B4C0C, 0xDDCBBa3666f578E3F09516f21Ff85BFee859AB5e); // SPY
        _seedQuoteBridge(0x1b0E319c6A659F002271B69dB8A7df2F911c153E, 0xc6BCC95043DC48C204bB2D57fb264a10Efe0a607); // GME
        _seedQuoteBridge(0x2e0847E8910a9732eB3fb1bb4b70a580ADAD4FE3, 0x8c2B4303fA0B99d07A5D3E9411497A277e65b673); // GOOGL
        _seedQuoteBridge(0x322F0929c4625eD5bAd873c95208D54E1c003b2d, 0xA953CA88ff430e9487c60cA34d757414f4efdA07); // TSLA
        _seedQuoteBridge(0x411eFb0E7f985935DAec3D4C3ebaEa0d0AD7D89f, 0xCa2734C70E3C348eDcDA36A6478c9275A0Ff0c90); // SLV
        _seedQuoteBridge(0x4a0E65A3EcceC6dBe60AE065F2e7bb85Fae35eEa, 0xC3c9F0171490Ef0F4536fe493F3b0EbB5ee0CB5e); // SPCX
        _seedQuoteBridge(0x58FfE4a942d3885bAa22D7520691F611EF09e7AA, 0x91280dB3392EA92C08d8134b5760Fb4798B69547); // TSM
        _seedQuoteBridge(0x6330D8C3178a418788dF01a47479c0ce7CCF450b, 0x6707aeAc7D0e519B083219d27BB427364363183A); // COIN
        _seedQuoteBridge(0x86923f96303D656E4aa86D9d42D1e57ad2023fdC, 0x5ca1B5e6Cb510b3bf53E7cd8f7d9B5a71b4a4dc0); // AMD
        _seedQuoteBridge(0x894E1EC2D74FFE5AEF8Dc8A9e84686acCB964F2A, 0x61be5Bfbaf17aE28Bf68006103B2e78Fe6112638); // PLTR
        _seedQuoteBridge(0x92FD66527192E3e61d4DDd13322Aa222DE86F9B5, 0x7F310e3D05E575Bd449E4484eF5Da15863ea43B1); // SGOV
        _seedQuoteBridge(0x941AE714EC6D8130c7B75d67160Ca08f1e7d11Dd, 0x61346CD249a6453fBa2ADa35f210376ac0B4957c); // DELL
        _seedQuoteBridge(0xaF3D76f1834A1d425780943C99Ea8A608f8a93f9, 0x8bb3514e2204E1cDF3Ac149EFEe7Ff04D91B719f); // AAPL
        _seedQuoteBridge(0xB90A19fF0Af67f7779afF50A882A9CfF42446400, 0x995c1Ad5Eb998b1BdD89F515C4BB64760c411b62); // SNDK
        _seedQuoteBridge(0xc0D6457C16Cc70d6790Dd43521C899C87ce02f35, 0xa4BdB396a69617eb7F70E2cc1EF526f7340b1B0d); // META
        _seedQuoteBridge(0xc72b96e0E48ecd4DC75E1e45396e26300BC39681, 0x1b375A9c30Ac43391AEFaE1bcf3a988D92458725); // INTC
        _seedQuoteBridge(0xd0601CE157Db5bdC3162BbaC2a2C8aF5320D9EEC, 0x62AB521f71431f78ac374CdbadC6cda3c8916b6C); // NVDA
        _seedQuoteBridge(0xD5f3879160bc7c32ebb4dC785F8a4F505888de68, 0xA40D00a55d43bA2d188039DCF88bD68f4F133E78); // QQQ
        _seedQuoteBridge(0xdF0992E440dD0be65BD8439b609d6D4366bf1CB5, 0x754DdD4bF8E8635B4301a7f4Af2Ea7A82AB6cEA7); // CRCL
        _seedQuoteBridge(0xec262a75e413fAfD0dF80480274532C79D42da09, 0x70504a6FafdbfB75fE971FAA4dD716e79aC5624c); // MSTR
        _seedQuoteBridge(0xfF080c8ce2E5feadaCa0Da81314Ae59D232d4afD, 0x301F48EC369BB3bfA0bC04d44A79037aa0EE2340); // MU
    }

    function _setImageURI(string memory uri) internal {
        bytes memory b = bytes(uri);
        if (b.length > 256) revert BadLen();
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            if (c == 0x00 || c == 0x22 || c < 0x20) revert BadPool();
        }
        imageURI = uri;
        emit ImageURISet(uri);
    }

    function _quoteUnit(address token) internal pure returns (uint256) {
        if (token == USDG) return 1e6;
        return 1e18;
    }

    function _spotQuotePerToken(address token) internal view returns (uint256) {
        PoolKey memory key = v4Key[token];
        (, int24 tick, , ) = IStateView(v4StateView).getSlot0(poolIdOf[token]);
        return IUniTwapOracle(twapOracle).quoteAtTick(tick, 1e18, token == key.currency0);
    }

    function _swapV3Exact(address tokenIn, address tokenOut, address pool, uint256 amountIn, uint256 minOut)
        internal
        returns (uint256 got)
    {
        uint24 fee = IUniV3Pool(pool).fee();
        IERC20(tokenIn).approve(swapRouter, amountIn);
        got = ISwapRouter02(swapRouter).exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
        IERC20(tokenIn).approve(swapRouter, 0);
    }

    function _swapV4Exact(address tokenIn, address tokenOut, uint256 amountIn, uint256 minOut)
        internal
        returns (uint256 got)
    {
        bytes memory ret = IPoolManager(v4Manager).unlock(abi.encode(tokenIn, tokenOut, amountIn, minOut));
        got = abi.decode(ret, (uint256));
    }

    function _swapQuotedBuy(address token, address quote, uint256 wethIn, uint256 minTokenOut) internal {
        address bridge = quoteBridgeV3[quote];
        if (bridge == address(0)) revert BadPool();
        uint256 pxQuote = IHoodxView(address(this)).priceWethWad(quote);
        uint256 quotedQuote = (wethIn * _quoteUnit(quote)) / pxQuote;
        uint256 quoteFloor = IHoodxView(address(this)).minOutFloor(quotedQuote);
        uint256 quoteGot = _swapV3Exact(weth, quote, bridge, wethIn, quoteFloor);
        if (isV4[token]) {
            _swapV4Exact(quote, token, quoteGot, minTokenOut);
        } else {
            _swapV3Exact(quote, token, poolOf[token], quoteGot, minTokenOut);
        }
    }

    function _swapQuotedSell(address token, address quote, uint256 tokenIn, uint256 minWethOut) internal {
        address bridge = quoteBridgeV3[quote];
        if (bridge == address(0)) revert BadPool();
        uint256 quotedQuote;
        uint256 quoteGot;
        if (isV4[token]) {
            quotedQuote = _spotQuotePerToken(token);
            quotedQuote = (tokenIn * quotedQuote) / 1e18;
            uint256 quoteFloor = IHoodxView(address(this)).minOutFloor(quotedQuote);
            quoteGot = _swapV4Exact(token, quote, tokenIn, quoteFloor);
        } else {
            address pool = poolOf[token];
            quotedQuote = IUniTwapOracle(twapOracle).quotePerBase(pool, token, quote, 1e18, TWAP_SECS);
            quotedQuote = (tokenIn * quotedQuote) / 1e18;
            uint256 quoteFloor = IHoodxView(address(this)).minOutFloor(quotedQuote);
            quoteGot = _swapV3Exact(token, quote, pool, tokenIn, quoteFloor);
        }
        uint256 pxQuote = IHoodxView(address(this)).priceWethWad(quote);
        uint256 quotedWeth = (quoteGot * pxQuote) / _quoteUnit(quote);
        uint256 wethFloor = IHoodxView(address(this)).minOutFloor(quotedWeth);
        if (wethFloor < minWethOut) revert Slippage();
        _swapV3Exact(quote, weth, bridge, quoteGot, minWethOut);
    }
}

contracts/HoodxIndex.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IUniTwapOracle, IStateView, PoolKey} from "./UniTwap.sol";
import {HoodxStorage, IERC20, IWETH} from "./HoodxStorage.sol";
import {HoodxSwap} from "./HoodxSwap.sol";

/// @title HoodxIndex — trustless ETH in / ETH out meme basket
/// @notice Cloneable vault. One share starts at $100 of ETH. Join mints at live
///         NAV per share, capped at net ETH in, with a required minShares (EIP-4626
///         inflation / sandwich). Dead shares capture donations. V4 mint NAV uses
///         max(spot, last tick) so a flash dump cannot cheapen the basket.
///         `owner` is the curator (two-step transfer). `creator` keeps the fee cut.
///         Swap/bind live in HoodxSwap via delegatecall so this clone stays under 24kb.

contract HoodxIndex is HoodxStorage {
    address public immutable twapOracle;
    address public immutable swapLogic;

    constructor(address twapOracle_, address swapLogic_) {
        if (twapOracle_ == address(0) || swapLogic_ == address(0) || swapLogic_.code.length == 0) revert Zero();
        twapOracle = twapOracle_;
        swapLogic = swapLogic_;
        implLock = true;
    }

    function _dlg(bytes memory data) internal returns (bytes memory ret) {
        bool ok;
        (ok, ret) = swapLogic.delegatecall(data);
        if (!ok) {
            assembly {
                revert(add(ret, 32), mload(ret))
            }
        }
    }

    function initialize(
        InitParams calldata p,
        address[] calldata constituents,
        bytes32[] calldata pools
    ) external {
        if (implLock || factory != address(0)) revert AlreadyInit();
        if (p.creator == address(0) || p.protocol == address(0) || p.weth == address(0) || p.router == address(0)) {
            revert Zero();
        }
        if (p.v4Manager == address(0) || p.v4StateView == address(0) || p.v4Posm == address(0)) revert Zero();
        if (constituents.length < 2 || constituents.length > 24) revert BadLen();
        if (constituents.length != pools.length) revert BadLen();
        if (uint256(p.protocolFeeBps) + uint256(p.creatorFeeBps) > MAX_FEE_BPS) revert MaxFee();
        if (bytes(p.name).length == 0 || bytes(p.symbol).length == 0) revert Zero();
        factory = msg.sender;
        owner = p.creator;
        creator = p.creator;
        creatorRecipient = p.recipient == address(0) ? p.creator : p.recipient;
        protocol = p.protocol;
        weth = p.weth;
        swapRouter = p.router;
        v4Manager = p.v4Manager;
        v4StateView = p.v4StateView;
        v4Posm = p.v4Posm;
        name = p.name;
        symbol = p.symbol;
        protocolFeeBps = p.protocolFeeBps;
        creatorFeeBps = p.creatorFeeBps;
        cashTargetBps = 2500;
        minDeposit = 0.02 ether;
        minFirstDeposit = p.minFirstDeposit;
        minSleeveWeth = 0.004 ether;
        genesisEthPerShare = 0.04 ether; // $100 at $2500 ETH; owner can peg before first mint
        if (bytes(p.imageURI).length != 0) {
            _dlg(abi.encodeWithSelector(HoodxSwap.setImageURIRaw.selector, p.imageURI));
        }
        _dlg(abi.encodeWithSelector(HoodxSwap.initQuotes.selector));
        for (uint256 i; i < constituents.length; i++) {
            _dlg(abi.encodeWithSelector(HoodxSwap.addTokenRaw.selector, constituents[i], pools[i]));
        }
        uint16 each = uint16((BPS_DENOM - cashTargetBps) / constituents.length);
        for (uint256 i; i < constituents.length; i++) {
            targetBps[constituents[i]] = each;
        }
    }

    receive() external payable {
        if (msg.sender != weth && msg.sender != v4Manager) revert TransferFailed();
    }

    function nTokens() external view returns (uint256) {
        return tokens.length;
    }

    function tokenAt(uint256 i) external view returns (address) {
        return tokens[i];
    }

    function issueFeeBps() public view returns (uint16) {
        return protocolFeeBps + creatorFeeBps;
    }

    function cashBps() public view returns (uint256) {
        uint256 used;
        for (uint256 i; i < tokens.length; i++) used += targetBps[tokens[i]];
        return BPS_DENOM - used;
    }

    function wethBuffer() public view returns (uint256) {
        return IERC20(weth).balanceOf(address(this));
    }

    /// @dev WETH wei per one full token (`10 ** decimals`). V3 TWAP or V4 spot × quote bridge.
    function priceWethWad(address token) public view returns (uint256) {
        if (token == weth) return 1e18;
        uint256 unit = _quoteUnit(token);
        if (allowedQuote[token] && quoteBridgeV3[token] != address(0)) {
            return IUniTwapOracle(twapOracle).priceWethWad(quoteBridgeV3[token], token, weth, unit, TWAP_SECS);
        }
        address quote = quoteOf[token];
        if (isV4[token]) {
            if (quote == address(0) || quote == weth) {
                PoolKey memory key = v4Key[token];
                return IUniTwapOracle(twapOracle).priceWethWadV4(v4StateView, poolIdOf[token], token, key.currency0, key.currency1, weth, unit);
            }
            uint256 quotePerToken = _spotQuotePerToken(token);
            uint256 wethPerQuote = priceWethWad(quote);
            return (quotePerToken * wethPerQuote) / _quoteUnit(quote);
        }
        address pool = poolOf[token];
        if (pool == address(0)) revert Listed();
        if (quote != address(0) && quote != weth) {
            uint256 quotePerToken = IUniTwapOracle(twapOracle).quotePerBase(pool, token, quote, unit, TWAP_SECS);
            uint256 wethPerQuote = priceWethWad(quote);
            return (quotePerToken * wethPerQuote) / _quoteUnit(quote);
        }
        return IUniTwapOracle(twapOracle).priceWethWad(pool, token, weth, unit, TWAP_SECS);
    }

    function oracleReady(address token) external view returns (bool) {
        if (!listed[token]) return false;
        if (!isV4[token] && poolOf[token] == address(0)) return false;
        try this.priceWethWad(token) returns (uint256 px) {
            return px > 0;
        } catch {
            return false;
        }
    }

    function quoteOut(address tokenIn, address tokenOut, uint256 amountIn) public view returns (uint256) {
        if (amountIn == 0) return 0;
        if (tokenIn == weth && listed[tokenOut]) {
            uint256 px = priceWethWad(tokenOut);
            return (amountIn * 1e18) / px;
        }
        if (tokenOut == weth && listed[tokenIn]) {
            uint256 px = priceWethWad(tokenIn);
            return (amountIn * px) / 1e18;
        }
        revert BadPair();
    }

    function minOutFloor(uint256 twapOut) public pure returns (uint256) {
        return (twapOut * (BPS_DENOM - MAX_SLIP_BPS)) / BPS_DENOM;
    }

    function cashShortfall() public view returns (uint256) {
        uint256 assets = totalAssets();
        if (assets == 0) return 0;
        uint256 want = (assets * uint256(cashTargetBps)) / BPS_DENOM;
        uint256 have = wethBuffer();
        return have >= want ? 0 : want - have;
    }

    function totalAssets() public view returns (uint256 assets) {
        assets = _nav(false);
    }

    function redeemableAssets() public view returns (uint256 assets) {
        assets = IERC20(weth).balanceOf(address(this)) + address(this).balance;
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            if (bal == 0 || !_canLiquidate(t)) continue;
            try this.priceWethWad(t) returns (uint256 px) {
                if (px != 0) assets += (bal * px) / 1e18;
            } catch {}
        }
    }

    /// @dev Mint pricing. V4 uses max(spot, lastPx) so a same-block dump cannot cheapen shares
    ///      (Indexed Finance: understate one name, mint the basket). V3 already TWAPs.
    function mintAssets() public view returns (uint256) {
        return _nav(true);
    }

    function _nav(bool mintPx) internal view returns (uint256 assets) {
        assets = IERC20(weth).balanceOf(address(this)) + address(this).balance;
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            if (bal == 0) continue;
            uint256 px = priceWethWad(t);
            if (mintPx && isV4[t]) {
                uint256 last = lastPxWad[t];
                if (last > px) px = last;
            }
            assets += (bal * px) / 1e18;
        }
    }

    function _liveSupply() internal view returns (uint256) {
        uint256 d = balanceOf[DEAD];
        uint256 s = totalSupply;
        return s > d ? s - d : 0;
    }

    function _virtualShares() internal view returns (uint256) {
        uint256 g = genesisEthPerShare;
        if (g == 0) return 1;
        uint256 vs = (VIRTUAL_ASSETS * 1e18) / g;
        return vs == 0 ? 1 : vs;
    }

    function _snapshotPx() internal {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            if (IERC20(t).balanceOf(address(this)) == 0) continue;
            lastPxWad[t] = priceWethWad(t);
        }
    }

    /// @dev Entry price. Empty + no assets = genesis. Unsolicited WETH is priced as if
    ///      dead shares already existed, so previewDeposit cannot hide a donation.
    function sharePrice() public view returns (uint256) {
        uint256 supply = totalSupply;
        uint256 nav = mintAssets();
        if (supply == 0 || _liveSupply() == 0) {
            if (nav == 0) return genesisEthPerShare;
            uint256 denom = supply == 0 ? _virtualShares() : supply;
            return (nav * 1e18) / denom;
        }
        return (nav * 1e18) / supply;
    }

    function position(address who)
        external
        view
        returns (uint256 shares, uint256 value, uint256 cost, uint256 price)
    {
        price = sharePrice();
        shares = balanceOf[who];
        cost = costBasis[who];
        uint256 supply = totalSupply;
        if (supply == 0 || shares == 0) return (shares, 0, cost, price);
        value = (shares * redeemableAssets()) / supply;
    }

    /// @dev Best-case shares (no slip). Fill drag can mint less; never more than this.
    ///      Callers MUST pass a minShares on deposit — preview is manipulable (EIP-4626).
    function previewDeposit(uint256 weiIn) public view returns (uint256 shares, uint256 fee) {
        (uint256 proto, uint256 creat) = _fees(weiIn);
        fee = proto + creat;
        uint256 net = weiIn - fee;
        uint256 price = sharePrice();
        if (price == 0) return (0, fee);
        shares = (net * 1e18) / price;
    }

    function previewFees(uint256 weiIn) external view returns (uint256 protocolFee, uint256 creatorFee) {
        return _fees(weiIn);
    }

    function previewWithdraw(uint256 shares) public view returns (uint256 net, uint256 fee) {
        uint256 supply = totalSupply;
        if (supply == 0 || shares == 0) return (0, 0);
        uint256 value = (shares * redeemableAssets()) / supply;
        fee = (value * redeemFeeBps) / BPS_DENOM;
        net = value - fee;
    }

    function previewBuy(uint256 weiIn) public view returns (uint256 spent, uint256 wethKept, uint256 names) {
        (, uint256 fee) = previewDeposit(weiIn);
        if (weiIn <= fee) return (0, 0, 0);
        uint256 net = weiIn - fee;
        uint256 supply = totalSupply;
        uint256 assetsBefore = totalAssets();
        if (supply == 0 || assetsBefore == 0) {
            (spent, names) = _previewTargets(net);
        } else {
            (spent, names) = _previewReplicate(net, assetsBefore);
        }
        wethKept = net - spent;
    }

    function previewSell(uint256 shares) public view returns (uint256 minEthOut, uint256 names) {
        uint256 supply = totalSupply;
        if (supply == 0 || shares == 0 || shares > supply) return (0, 0);
        uint256 wethBal = IERC20(weth).balanceOf(address(this));
        bool sweep = shares == supply || shares == _liveSupply();
        minEthOut = sweep ? wethBal : (wethBal * shares) / supply;
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            uint256 amt = sweep ? bal : (bal * shares) / supply;
            if (amt == 0) continue;
            if (!_canLiquidate(t)) continue;
            uint256 floor = _minOutOrZero(t, weth, amt);
            if (floor == 0) continue;
            minEthOut += floor;
            names++;
        }
    }

    function canWithdraw(uint256 shares) external view returns (bool) {
        (uint256 minOut, ) = previewSell(shares);
        return minOut > 0;
    }

    /// @dev minShares is required. previewDeposit is manipulable (EIP-4626); the router/HUD
    ///      must set minShares from preview minus known slip. 0 is rejected.
    function deposit(uint256 minShares) external payable nonReentrant returns (uint256 shares) {
        if (paused) revert Paused();
        if (minShares == 0) revert TooSmall();
        uint256 gross = msg.value;
        if (gross < minDeposit) revert TooSmall();
        (uint256 proto, uint256 creat) = _fees(gross);
        uint256 net = gross - proto - creat;
        uint256 supply = totalSupply;
        uint256 mintNav = mintAssets() - gross;
        IWETH(weth).deposit{value: gross}();
        if (proto > 0) {
            if (!IERC20(weth).transfer(protocol, proto)) revert TransferFailed();
        }
        if (creat > 0) {
            if (!IERC20(weth).transfer(creatorRecipient, creat)) revert TransferFailed();
        }
        if (_liveSupply() == 0) {
            if (gross < minFirstDeposit) revert TooSmall();
            if (balanceOf[DEAD] == 0) _mint(DEAD, _virtualShares());
            supply = totalSupply;
        } else {
            _assertPriced();
            if (mintNav == 0) revert Zero();
        }
        for (uint256 i; i < tokens.length; i++) {
            if (!isV4[tokens[i]]) warmOracle(tokens[i]);
        }
        uint256 price = mintNav == 0 ? genesisEthPerShare : (mintNav * 1e18) / supply;
        _deployNet(net, mintNav, supply);
        uint256 assetsAfter = mintAssets();
        uint256 credited = assetsAfter > mintNav ? assetsAfter - mintNav : 0;
        if (credited > net) credited = net;
        if (credited == 0 || price == 0) revert TooSmall();
        shares = (credited * 1e18) / price;
        if (shares == 0 || shares < minShares) revert Slippage();
        costBasis[msg.sender] += gross;
        _mint(msg.sender, shares);
        _snapshotPx();
        emit Deposit(msg.sender, gross, shares, proto, creat, price);
    }

    /// @dev Exits stay open when paused so the curator cannot trap ETH.
    ///      Sells this user's slice of every name, then unwraps WETH.
    function withdraw(uint256 shares, uint256 minEthOut) external nonReentrant returns (uint256 net) {
        if (shares == 0 || balanceOf[msg.sender] < shares) revert Zero();
        _assertPriced();
        uint256 supply = totalSupply;
        uint256 price = (totalAssets() * 1e18) / supply;
        uint256 wethBefore = IERC20(weth).balanceOf(address(this));
        bool sweep = shares == supply || shares == _liveSupply();
        uint256 cashTake = sweep ? wethBefore : (wethBefore * shares) / supply;
        _liquidate(shares, supply, sweep);
        uint256 proceeds = IERC20(weth).balanceOf(address(this)) - wethBefore;
        net = cashTake + proceeds;
        if (net == 0) revert NeedBuffer();
        if (net < minEthOut) revert Slippage();
        uint256 fee = (net * redeemFeeBps) / BPS_DENOM;
        net = net - fee;
        _shiftCost(msg.sender, address(0), shares);
        _burn(msg.sender, shares);
        if (fee > 0) {
            if (!IERC20(weth).transfer(protocol, fee)) revert TransferFailed();
        }
        IWETH(weth).withdraw(net);
        (bool ok, ) = msg.sender.call{value: net}("");
        if (!ok) revert TransferFailed();
        _snapshotPx();
        emit Withdraw(msg.sender, shares, net, fee, price);
    }

    function setTargets(address[] calldata who, uint16[] calldata bps) external onlyOwner {
        if (who.length != bps.length) revert BadLen();
        uint256 used;
        uint256 nav = totalAssets();
        for (uint256 i; i < who.length; i++) {
            if (!listed[who[i]]) revert Listed();
            if (bps[i] > 0 && nav > 0) {
                uint256 sleeve = (nav * uint256(bps[i])) / BPS_DENOM;
                if (sleeve < minSleeveWeth) revert DustSleeve();
            }
            used += bps[i];
        }
        if (used > BPS_DENOM - cashTargetBps) revert CashFloor();
        for (uint256 i; i < tokens.length; i++) targetBps[tokens[i]] = 0;
        for (uint256 i; i < who.length; i++) targetBps[who[i]] = bps[i];
        emit Targets(who, bps);
    }

    function constituents() external view returns (address[] memory) {
        return tokens;
    }

    function addToken(address token, bytes32 poolRef) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.addTokenRaw.selector, token, poolRef));
    }

    function addTokens(address[] calldata who, bytes32[] calldata pools) external onlyOwner {
        if (who.length != pools.length) revert BadLen();
        for (uint256 i; i < who.length; i++) {
            _dlg(abi.encodeWithSelector(HoodxSwap.addTokenRaw.selector, who[i], pools[i]));
        }
    }

    function removeToken(address token) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.removeTokenRaw.selector, token));
    }

    function removeTokens(address[] calldata who) external onlyOwner {
        for (uint256 i; i < who.length; i++) {
            _dlg(abi.encodeWithSelector(HoodxSwap.removeTokenRaw.selector, who[i]));
        }
    }

    function strandToken(address token) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.strandTokenRaw.selector, token));
    }

    function claimDust(address token) external nonReentrant {
        _dlg(abi.encodeWithSelector(HoodxSwap.claimDustRaw.selector, token));
    }

    /// @dev Rebind a zero-balance name to a new pool (e.g. PROMETHEUS/SPCX). Does not touch balances.
    function rebindToken(address token, bytes32 poolRef) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.rebindTokenRaw.selector, token, poolRef));
    }

    function setCreatorRecipient(address who) external {
        if (msg.sender != creator) revert NotCreator();
        _assertPayTo(who, false);
        creatorRecipient = who;
        emit CreatorRecipient(who);
    }

    /// @dev Wallet/Blockscout token image. HTTPS or IPFS, max 256 chars, no quotes.
    function setImageURI(string calldata uri) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.setImageURIRaw.selector, uri));
    }

    /// @dev ERC-7572 metadata. Explorers read `image` from this JSON.
    function contractURI() external view returns (string memory) {
        return string.concat(
            "data:application/json;utf8,{\"name\":\"",
            _jsonSafe(name),
            "\",\"symbol\":\"",
            _jsonSafe(symbol),
            "\",\"description\":\"HOODX index on Robinhood Chain\",\"image\":\"",
            imageURI,
            "\",\"external_url\":\"https://www.xhoodindex.com\"}"
        );
    }

    /// @dev Register a quote token (RH stock 18-dec, or USDG 6-dec) with its WETH V3 bridge.
    function setQuoteBridge(address quote, address v3Bridge) external onlyOwner {
        _dlg(abi.encodeWithSelector(HoodxSwap.setQuoteBridgeRaw.selector, quote, v3Bridge));
    }

    /// @dev WETH ↔ listed name on the bound V3 or V4 pool. Fee comes from the pool.
    ///      minOut must be ≥ 97% of the on-chain quote so the curator cannot sandwich the vault.
    function swapV3(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin)
        external
        onlyOwner
        nonReentrant
    {
        if (amountIn == 0 || amountOutMin == 0 || swapRouter == address(0)) revert Zero();
        bool buy = tokenIn == weth && listed[tokenOut];
        bool sell = tokenOut == weth && listed[tokenIn];
        if (!buy && !sell) revert BadPair();
        if (buy && paused) revert Paused();
        uint256 floor = minOutFloor(quoteOut(tokenIn, tokenOut, amountIn));
        if (floor == 0 || amountOutMin < floor) revert Slippage();
        _swap(tokenIn, tokenOut, amountIn, amountOutMin);
        if (buy) _assertCashFloor();
        _snapshotPx();
        emit Rebalanced(tokenIn, tokenOut, amountIn, amountOutMin);
    }

    /// @dev Permissionless. V3 only — V4 marks at spot, so a dump+sell would drain at the
    ///      crashed tick. Owner swapV3 still rebalances V4. 3% min-out vs TWAP.
    function restoreCash(address token, uint256 amountIn) external nonReentrant {
        if (!listed[token]) revert Listed();
        if (isV4[token]) revert BadPool();
        uint256 shortfall = cashShortfall();
        if (shortfall == 0) revert CashFloor();
        uint256 px = priceWethWad(token);
        uint256 maxIn = (shortfall * 1e18) / px;
        maxIn = (maxIn * (BPS_DENOM + MAX_SLIP_BPS)) / BPS_DENOM;
        if (maxIn == 0) revert TooSmall();
        uint256 bal = IERC20(token).balanceOf(address(this));
        if (amountIn == 0 || amountIn > bal) revert Zero();
        if (amountIn > maxIn) amountIn = maxIn;
        uint256 minOut = minOutFloor((amountIn * px) / 1e18);
        if (minOut == 0) revert TooSmall();
        _swap(token, weth, amountIn, minOut);
        _snapshotPx();
        emit Restored(token, amountIn, minOut);
    }

    function warmOracle(address token) public {
        _dlg(abi.encodeWithSelector(HoodxSwap.warmOracleRaw.selector, token));
    }

    function warmOracles() external {
        for (uint256 i; i < tokens.length; i++) warmOracle(tokens[i]);
    }

    function setCreatorFee(uint16 bps) external {
        if (msg.sender != creator) revert NotCreator();
        if (uint256(protocolFeeBps) + uint256(bps) > MAX_FEE_BPS) revert MaxFee();
        creatorFeeBps = bps;
        emit CreatorFee(bps);
    }

    function setGenesisEthPerShare(uint256 weiPerShare) external onlyOwner {
        if (totalSupply != 0) revert Started();
        if (weiPerShare < 0.01 ether || weiPerShare > 0.25 ether) revert TooSmall();
        genesisEthPerShare = weiPerShare;
        emit Genesis(weiPerShare);
    }

    function setFloors(uint256 minDep, uint256 minFirst, uint256 minSleeve, uint16 cashBps_) external onlyOwner {
        if (minDep < 0.001 ether || minFirst < minDep) revert TooSmall();
        if (minSleeve < 0.001 ether) revert TooSmall();
        if (cashBps_ < MIN_CASH_BPS || cashBps_ > 5000) revert CashFloor();
        minDeposit = minDep;
        minFirstDeposit = minFirst;
        minSleeveWeth = minSleeve;
        cashTargetBps = cashBps_;
        emit Floors(minDep, minFirst, minSleeve, cashBps_);
    }

    function setPaused(bool v) external onlyOwner {
        paused = v;
        emit PausedSet(v);
    }

    /// @dev Nominate a curator. They must `acceptOwnership` from that wallet.
    ///      Does not move `creator` or `creatorRecipient` — handing the book cannot steal the cut.
    function transferOwnership(address next) external onlyOwner {
        _assertPayTo(next, true);
        pendingOwner = next;
        emit OwnershipTransferStarted(owner, next);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        _assertPayTo(msg.sender, true);
        pendingOwner = address(0);
        owner = msg.sender;
        emit OwnerSet(msg.sender);
    }

    function cancelOwnershipTransfer() external onlyOwner {
        address pending = pendingOwner;
        if (pending == address(0)) revert Zero();
        pendingOwner = address(0);
        emit OwnershipTransferCanceled(owner, pending);
    }

    /// @dev Block 0 / vault / WETH / dead / routers so a typo cannot brick or burn the role.
    ///      `asCurator` also rejects the current owner (no-op self-transfer).
    function _assertPayTo(address who, bool asCurator) internal view {
        if (who == address(0)) revert Zero();
        if (asCurator && who == owner) revert BadOwner();
        if (
            who == address(this) ||
            who == weth ||
            who == DEAD ||
            who == factory ||
            who == swapRouter ||
            who == v4Manager ||
            who == v4StateView ||
            who == v4Posm
        ) revert BadOwner();
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            if (allowed < value) revert Zero();
            allowance[from][msg.sender] = allowed - value;
        }
        _move(from, to, value);
        return true;
    }

    function _deployNet(uint256 net, uint256 assetsBefore, uint256 supply) internal {
        uint256 spent;
        uint256 names;
        if (supply == 0 || assetsBefore == 0) {
            (spent, names) = _deployTargets(net);
        } else {
            (spent, names) = _replicate(net, assetsBefore);
        }
        emit Deployed(spent, names);
    }

    function _deployTargets(uint256 net) internal returns (uint256 spent, uint256 names) {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 sleeve = (net * uint256(targetBps[t])) / BPS_DENOM;
            if (sleeve < minSleeveWeth) continue;
            uint256 floor = _minOutOrZero(weth, t, sleeve);
            if (floor == 0) continue;
            if (!_swapOrSkip(weth, t, sleeve, floor)) continue;
            spent += sleeve;
            names++;
        }
    }

    function _replicate(uint256 net, uint256 assetsBefore) internal returns (uint256 spent, uint256 names) {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            if (bal == 0) continue;
            uint256 val = (bal * priceWethWad(t)) / 1e18;
            uint256 sleeve = (net * val) / assetsBefore;
            if (sleeve == 0) continue;
            uint256 floor = _minOutOrZero(weth, t, sleeve);
            if (floor == 0) continue;
            if (!_swapOrSkip(weth, t, sleeve, floor)) continue;
            spent += sleeve;
            names++;
        }
    }

    function _liquidate(uint256 shares, uint256 supply, bool sweep) internal {
        uint256 names;
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            uint256 amt = sweep ? bal : (bal * shares) / supply;
            if (amt == 0) continue;
            if (!_canLiquidate(t)) continue;
            uint256 floor = _minOutOrZero(t, weth, amt);
            if (floor == 0) continue;
            if (!_swapOrSkip(t, weth, amt, floor)) continue;
            names++;
        }
        emit Liquidated(shares, names);
    }

    function _previewTargets(uint256 net) internal view returns (uint256 spent, uint256 names) {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 sleeve = (net * uint256(targetBps[t])) / BPS_DENOM;
            if (sleeve < minSleeveWeth) continue;
            if (_minOutOrZero(weth, t, sleeve) == 0) continue;
            spent += sleeve;
            names++;
        }
    }

    function _previewReplicate(uint256 net, uint256 assetsBefore) internal view returns (uint256 spent, uint256 names) {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            uint256 bal = IERC20(t).balanceOf(address(this));
            if (bal == 0) continue;
            uint256 val = (bal * priceWethWad(t)) / 1e18;
            uint256 sleeve = (net * val) / assetsBefore;
            if (sleeve == 0) continue;
            if (_minOutOrZero(weth, t, sleeve) == 0) continue;
            spent += sleeve;
            names++;
        }
    }

    function _minOutOrZero(address tokenIn, address tokenOut, uint256 amountIn) internal view returns (uint256) {
        try this.quoteOut(tokenIn, tokenOut, amountIn) returns (uint256 quoted) {
            return minOutFloor(quoted);
        } catch {
            return 0;
        }
    }

    /// @dev Hooked V4 pools cannot be sold with empty hookData — skip on redeem rather than brick exits.
    function _canLiquidate(address token) internal view returns (bool) {
        if (!isV4[token]) return poolOf[token] != address(0);
        PoolKey memory key = v4Key[token];
        return key.hooks == address(0);
    }

    function execSwap(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _swap(tokenIn, tokenOut, amountIn, amountOutMin);
    }

    function _swapOrSkip(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin)
        internal
        returns (bool)
    {
        try this.execSwap(tokenIn, tokenOut, amountIn, amountOutMin) {
            return true;
        } catch {
            return false;
        }
    }

    function _swap(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOutMin) internal {
        _dlg(abi.encodeWithSelector(HoodxSwap.swap.selector, tokenIn, tokenOut, amountIn, amountOutMin));
    }

    /// @dev PoolManager callback. Settles the vault as the locker so V4 swaps
    ///      do not need Permit2 / Universal Router.
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        return _dlg(msg.data);
    }

    function _fees(uint256 weiIn) internal view returns (uint256 proto, uint256 creat) {
        proto = (weiIn * protocolFeeBps) / BPS_DENOM;
        creat = (weiIn * creatorFeeBps) / BPS_DENOM;
    }

    function _shiftCost(address from, address to, uint256 shares) internal {
        uint256 bal = balanceOf[from];
        uint256 cut = (costBasis[from] * shares) / bal;
        costBasis[from] -= cut;
        if (to != address(0)) costBasis[to] += cut;
    }

    function _mint(address to, uint256 value) internal {
        if (to == address(0) || value == 0) revert Zero();
        totalSupply += value;
        balanceOf[to] += value;
        emit Transfer(address(0), to, value);
    }

    function _burn(address from, uint256 value) internal {
        if (balanceOf[from] < value) revert Zero();
        balanceOf[from] -= value;
        totalSupply -= value;
        emit Transfer(from, address(0), value);
    }

    function _move(address from, address to, uint256 value) internal {
        if (to == address(0) || value == 0) revert Zero();
        if (balanceOf[from] < value) revert Zero();
        _shiftCost(from, to, value);
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _assertPriced() internal view {
        for (uint256 i; i < tokens.length; i++) {
            address t = tokens[i];
            if (IERC20(t).balanceOf(address(this)) == 0) continue;
            if (!_canLiquidate(t)) continue;
            if (priceWethWad(t) == 0) revert Unpriced();
        }
    }

    function _assertCashFloor() internal view {
        uint256 assets = totalAssets();
        if (assets == 0) return;
        if (wethBuffer() * BPS_DENOM < assets * uint256(cashTargetBps)) revert CashFloor();
    }

    function _jsonSafe(string memory s) internal pure returns (string memory) {
        bytes memory b = bytes(s);
        bytes memory out = new bytes(b.length);
        uint256 n;
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            if (c == 0x22 || c == 0x5c || c < 0x20) continue;
            out[n] = c;
            n++;
        }
        bytes memory trimmed = new bytes(n);
        for (uint256 j; j < n; j++) trimmed[j] = out[j];
        return string(trimmed);
    }

    function _quoteUnit(address token) internal pure returns (uint256) {
        if (token == USDG) return 1e6;
        return 1e18;
    }

    function _spotQuotePerToken(address token) internal view returns (uint256) {
        PoolKey memory key = v4Key[token];
        (, int24 tick, , ) = IStateView(v4StateView).getSlot0(poolIdOf[token]);
        return IUniTwapOracle(twapOracle).quoteAtTick(tick, 1e18, token == key.currency0);
    }
}

contracts/HoodxFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {HoodxIndex} from "./HoodxIndex.sol";
import {HoodxStorage} from "./HoodxStorage.sol";

/// @title HoodxFactory — mint a meme index, drop the link, earn a cut

/// @title HoodxFactory — mint a meme index, drop the link, earn a cut
/// @notice Isolated side project. Not the LP desk.
///
/// create() clones HoodxIndex. Each constituent must ship a Uni V3 WETH or USDG
/// pool, a Uni V4 ETH/WETH pool, or a Uni V4 RH stock/USDG quote pool.
/// Slug `696x` is reserved (create696x, owner-only). Friends join via /i/{slug}.
/// Token image URI is set at create (ERC-7572 contractURI) and can be updated by the curator.

contract HoodxFactory {
    address public owner;
    address public immutable implementation;
    address public immutable weth;
    address public immutable swapRouter;
    address public immutable v4Manager;
    address public immutable v4StateView;
    address public immutable v4Posm;
    address public treasury;
    uint16 public protocolFeeBps = 10;
    uint16 public constant MAX_CREATOR_FEE_BPS = 50;
    uint16 public constant MAX_PROTOCOL_FEE_BPS = 50;

    mapping(string => address) public bySlug;
    mapping(address => string) public slugOf;
    address[] public all;

    error NotOwner();
    error Zero();
    error BadSlug();
    error Taken();
    error BadLen();
    error MaxFee();

    event Created(
        address indexed vault,
        address indexed creator,
        string slug,
        string name,
        string symbol,
        uint16 creatorFeeBps
    );

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(
        address weth_,
        address router_,
        address treasury_,
        address v4Manager_,
        address v4StateView_,
        address v4Posm_,
        address implementation_
    ) {
        if (weth_ == address(0) || router_ == address(0) || treasury_ == address(0)) revert Zero();
        if (v4Manager_ == address(0) || v4StateView_ == address(0) || v4Posm_ == address(0)) revert Zero();
        if (implementation_ == address(0) || implementation_.code.length == 0) revert Zero();
        owner = msg.sender;
        weth = weth_;
        swapRouter = router_;
        treasury = treasury_;
        v4Manager = v4Manager_;
        v4StateView = v4StateView_;
        v4Posm = v4Posm_;
        implementation = implementation_;
    }

    function indexCount() external view returns (uint256) {
        return all.length;
    }

    function indexAt(uint256 i) external view returns (address) {
        return all[i];
    }

    /// @dev First index. 696_eth watchlist. 0.08 ETH first mint (~$200).
    function create696x(
        address[] calldata tokens,
        bytes32[] calldata pools,
        address recipient_,
        string calldata imageURI_
    ) external onlyOwner returns (address) {
        return _create(msg.sender, "696x", "696X", "696x", tokens, pools, 40, 0.08 ether, recipient_, imageURI_);
    }

    /// @dev Anyone. Min 2 Uni V3 WETH/USDG or V4 ETH/quote names. First mint 0.02 ETH.
    function create(
        string calldata name_,
        string calldata symbol_,
        string calldata slug,
        address[] calldata tokens,
        bytes32[] calldata pools,
        uint16 creatorFeeBps,
        address recipient_,
        string calldata imageURI_
    ) external returns (address) {
        if (_eq(slug, "696x") || _eq(slug, "hoodx")) revert Taken();
        return _create(msg.sender, name_, symbol_, slug, tokens, pools, creatorFeeBps, 0.02 ether, recipient_, imageURI_);
    }

    function setTreasury(address who) external onlyOwner {
        if (who == address(0)) revert Zero();
        treasury = who;
    }

    function setProtocolFee(uint16 bps) external onlyOwner {
        if (bps > MAX_PROTOCOL_FEE_BPS) revert MaxFee();
        protocolFeeBps = bps;
    }

    function transferOwnership(address next) external onlyOwner {
        if (next == address(0)) revert Zero();
        owner = next;
    }

    function _create(
        address creator,
        string memory name_,
        string memory symbol_,
        string memory slug,
        address[] calldata tokens,
        bytes32[] calldata pools,
        uint16 creatorFeeBps,
        uint256 minFirst,
        address recipient_,
        string memory imageURI_
    ) internal returns (address vault) {
        if (!_okSlug(slug)) revert BadSlug();
        if (bySlug[slug] != address(0)) revert Taken();
        if (tokens.length < 2 || tokens.length > 24) revert BadLen();
        if (tokens.length != pools.length) revert BadLen();
        if (uint256(protocolFeeBps) + uint256(creatorFeeBps) > 100) revert MaxFee();
        if (creatorFeeBps > MAX_CREATOR_FEE_BPS) revert MaxFee();
        vault = _clone(implementation);
        HoodxIndex(payable(vault)).initialize(
            HoodxStorage.InitParams({
                creator: creator,
                protocol: treasury,
                weth: weth,
                router: swapRouter,
                v4Manager: v4Manager,
                v4StateView: v4StateView,
                v4Posm: v4Posm,
                name: name_,
                symbol: symbol_,
                protocolFeeBps: protocolFeeBps,
                creatorFeeBps: creatorFeeBps,
                minFirstDeposit: minFirst,
                recipient: recipient_,
                imageURI: imageURI_
            }),
            tokens,
            pools
        );
        bySlug[slug] = vault;
        slugOf[vault] = slug;
        all.push(vault);
        emit Created(vault, creator, slug, name_, symbol_, creatorFeeBps);
    }

    function _okSlug(string memory s) internal pure returns (bool) {
        bytes memory b = bytes(s);
        if (b.length < 3 || b.length > 16) return false;
        if (_eq(s, "create") || _eq(s, "factory") || _eq(s, "admin") || _eq(s, "index")) return false;
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            bool num = c >= 0x30 && c <= 0x39;
            bool low = c >= 0x61 && c <= 0x7a;
            if (!num && !low) return false;
        }
        return true;
    }

    function _eq(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }

    function _clone(address impl) internal returns (address instance) {
        bytes20 target = bytes20(impl);
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000000000000000000000)
            mstore(add(ptr, 0x14), target)
            mstore(add(ptr, 0x28), 0x5af43d82803e903d91602b57fd5bf30000000000000000000000000000000000)
            instance := create(0, ptr, 0x37)
        }
        if (instance == address(0)) revert Zero();
    }
}
